\pset tuples_only on
\pset format unaligned
SELECT jsonb_build_object('section','protection','connection',current_setting('default_transaction_read_only'),'transaction',current_setting('transaction_read_only'),'at',clock_timestamp());
-- Compact, explicit zero counts avoid stdout/env limits and ambiguous absent sections.
WITH targets AS (SELECT * FROM pkg_packing_records WHERE id IN (21,25,26,27,28))
SELECT jsonb_build_object('section','packing_closure','id',p.id,'code',p.code,'shift_id',p.shift_id,
 'eggs',p.total_eggs,'boxes',p.total_boxes,'grading_references',p.grading_codes_json,
 'handover', (SELECT jsonb_build_object('count',count(*),'rows',COALESCE(jsonb_agg(jsonb_build_object('id',h.id,'code',h.code,'boxes',h.box_count,'location',h.location)),'[]')) FROM pkg_handover_records h WHERE h.packing_code=p.code),
 'direct_inventory',(SELECT jsonb_build_object('count',count(*),'rows',COALESCE(jsonb_agg(jsonb_build_object('id',b.id,'batch_no',b.batch_no,'qty',b.qty,'qty_available',b.qty_available,'status',b.status,'source_no',b.source_no,'packaging_batch_ref',b.packaging_batch_ref)),'[]')) FROM inv_batches b WHERE b.packaging_batch_ref=p.code OR b.source_no=p.code OR b.batch_no=p.code),
 'direct_ledger',(SELECT jsonb_build_object('count',count(*),'ids',COALESCE(jsonb_agg(l.id),'[]')) FROM inv_ledger l WHERE l.ref_no=p.code OR l.batch_no=p.code OR l.batch_no IN (SELECT b.batch_no FROM inv_batches b WHERE b.packaging_batch_ref=p.code OR b.source_no=p.code)),
 'direct_allocations',(SELECT jsonb_build_object('count',count(*),'rows',COALESCE(jsonb_agg(to_jsonb(a)),'[]')) FROM sal_order_item_batch_allocations a WHERE a.batch_no=p.code OR a.batch_no IN (SELECT b.batch_no FROM inv_batches b WHERE b.packaging_batch_ref=p.code OR b.source_no=p.code)),
 'direct_allocation_actions',(SELECT count(*) FROM sal_order_item_batch_allocation_actions aa JOIN sal_order_item_batch_allocations a ON a.id=aa.allocation_id WHERE a.batch_no=p.code OR a.batch_no IN (SELECT b.batch_no FROM inv_batches b WHERE b.packaging_batch_ref=p.code OR b.source_no=p.code)),
 'legacy_order_items',(SELECT jsonb_build_object('count',count(*),'ids',COALESCE(jsonb_agg(to_jsonb(i)->'id'),'[]')) FROM sal_order_items i WHERE EXISTS (SELECT 1 FROM regexp_split_to_table(COALESCE(to_jsonb(i)->>'allocated_batch_no',''),'\s*,\s*') v WHERE v=p.code OR v IN (SELECT b.batch_no FROM inv_batches b WHERE b.packaging_batch_ref=p.code OR b.source_no=p.code))),
 'store_sale_items',(SELECT jsonb_build_object('count',count(*),'ids',COALESCE(jsonb_agg(to_jsonb(i)->'id'),'[]')) FROM sal_store_sale_items i WHERE to_jsonb(i)->>'batch_no'=p.code OR to_jsonb(i)->>'batch_no' IN (SELECT b.batch_no FROM inv_batches b WHERE b.packaging_batch_ref=p.code OR b.source_no=p.code)),
 'inferred_shift_inventory',(SELECT jsonb_build_object('count',count(*),'rows',COALESCE(jsonb_agg(jsonb_build_object('id',b.id,'batch_no',b.batch_no,'source_type',b.source_type,'qty',b.qty,'qty_available',b.qty_available)),'[]')) FROM inv_batches b WHERE b.collection_batch_ref='SHIFT-'||p.shift_id::text AND NOT (COALESCE(b.packaging_batch_ref,'')=p.code OR COALESCE(b.source_no,'')=p.code)),
 'inferred_site_day_inventory',(SELECT jsonb_build_object('count',count(*),'rows',COALESCE(jsonb_agg(jsonb_build_object('id',b.id,'batch_no',b.batch_no,'qty',b.qty,'qty_available',b.qty_available,'source_type',b.source_type)),'[]')) FROM inv_batches b JOIN pkg_work_shifts ws ON ws.id=p.shift_id WHERE b.egg_date=p.production_date AND b.source_type='PRODUCTION' AND (b.source_no=ws.site_id OR b.collection_batch_ref='SITE-'||ws.site_id))
) FROM targets p ORDER BY p.id;
SELECT jsonb_build_object('section','grading_reference_members','packing_id',p.id,'grading_code',refs.code,
 'grading_id',g.id,'grading_shift_id',g.shift_id,'grading_total',g.total_output,'status',g.status,
 'is_target_reference',g.id IN (53,54),'linked_sources',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',s.id,'house',s.house_code,'qty',l.input_qty)),'[]') FROM pkg_grading_source_links l JOIN pkg_source_batches s ON s.id=l.source_batch_id WHERE l.grading_id=g.id))
FROM pkg_packing_records p CROSS JOIN LATERAL jsonb_array_elements_text(p.grading_codes_json) refs(code)
LEFT JOIN pkg_grading_records g ON g.code=refs.code WHERE p.id IN (26,27,28) ORDER BY p.id,g.id;
SELECT jsonb_build_object('section','hashes','inventory_count',(SELECT count(*) FROM inv_batches),'inventory_hash',(SELECT md5(string_agg(to_jsonb(b)::text,E'\n' ORDER BY id)) FROM inv_batches b),'ledger_count',(SELECT count(*) FROM inv_ledger),'ledger_hash',(SELECT md5(string_agg(to_jsonb(l)::text,E'\n' ORDER BY id)) FROM inv_ledger l));
SELECT jsonb_build_object('section','schema_protection','columns',COALESCE(jsonb_agg(jsonb_build_object('table',table_name,'column',column_name,'type',data_type,'nullable',is_nullable,'default',column_default)),'[]')) FROM information_schema.columns WHERE table_schema='public' AND ((table_name IN ('pkg_work_shifts','pkg_source_batches','pkg_grading_records','pkg_packing_records') AND column_name='is_test') OR (table_name='pkg_packing_records' AND column_name IN ('status','void_reason','voided_at','voided_by','idempotency_key','payload_hash')));
